export type ParsedIndustriaDarLanceInstruction<
  TProgram extends string = typeof ECOL_LOTE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    payer: TAccountMetas[0];
    industria: TAccountMetas[1];
    industriaAssinante: TAccountMetas[2];
    industriaCarteira?: TAccountMetas[3] | undefined;
    industriaPart: TAccountMetas[4];
    config: TAccountMetas[5];
    lote: TAccountMetas[6];
    lance: TAccountMetas[7];
    systemProgram: TAccountMetas[8];
    eventAuthority: TAccountMetas[9];
    program: TAccountMetas[10];
  };
  data: IndustriaDarLanceInstructionData;
};

export function parseIndustriaDarLanceInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedIndustriaDarLanceInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 11,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === ECOL_LOTE_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      industria: getNextAccount(),
      industriaAssinante: getNextAccount(),
      industriaCarteira: getNextOptionalAccount(),
      industriaPart: getNextAccount(),
      config: getNextAccount(),
      lote: getNextAccount(),
      lance: getNextAccount(),
      systemProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getIndustriaDarLanceInstructionDataDecoder().decode(instruction.data),
  };
}
